import React from 'react';
import { MapPin } from 'lucide-react';

export default function JobCard({ job, user, onApply, isApplied }) {
  const userKeywords = user.profile.keywords.map(k => k.toLowerCase());
  const matchedKeywords = job.keywords.filter(jk => userKeywords.includes(jk.toLowerCase()));
  const matchPercentage = Math.round((matchedKeywords.length / Math.max(job.keywords.length, 1)) * 100);

  return (
    <div style={{
      background: 'white',
      padding: '20px',
      borderRadius: '12px',
      border: '1px solid #e0e0e0',
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'start'
    }}>
      <div style={{ flex: 1 }}>
        <div style={{ marginBottom: '12px' }}>
          <h3 style={{ fontSize: '17px', fontWeight: '700', margin: 0, color: '#1a1a1a', marginBottom: '4px' }}>{job.title}</h3>
          <p style={{ fontSize: '13px', color: '#999', margin: 0 }}>
            Posted {new Date(job.postedDate).toLocaleDateString()}
          </p>
        </div>

        <p style={{ fontSize: '13px', color: '#666', margin: '12px 0', lineHeight: '1.5' }}>{job.description}</p>

        <div style={{ display: 'flex', gap: '16px', fontSize: '13px', color: '#666', marginBottom: '12px' }}>
          <span style={{ display: 'flex', gap: '4px', alignItems: 'center' }}><MapPin size={14} /> {job.location}</span>
          <span>{job.salary}</span>
        </div>

        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
          {job.keywords.map((kw, i) => {
            const isMatched = userKeywords.includes(kw.toLowerCase());
            return (
              <span key={i} style={{
                background: isMatched ? '#d1fae5' : '#f0f0f0',
                padding: '4px 10px',
                borderRadius: '16px',
                fontSize: '12px',
                fontWeight: '600',
                color: isMatched ? '#059669' : '#667eea'
              }}>
                {kw}
              </span>
            );
          })}
        </div>
      </div>

      <div style={{ marginLeft: '20px', textAlign: 'right', minWidth: '100px' }}>
        <div style={{ fontSize: '28px', fontWeight: '700', color: matchPercentage >= 50 ? '#667eea' : '#999' }}>
          {matchPercentage}%
        </div>
        <p style={{ fontSize: '12px', color: '#999', margin: '4px 0' }}>Match</p>
        {onApply && (
          <button
            onClick={() => onApply(job.id)}
            disabled={isApplied}
            style={{
              width: '100%',
              padding: '8px 12px',
              marginTop: '8px',
              background: isApplied ? '#f0f0f0' : '#667eea',
              color: isApplied ? '#999' : 'white',
              border: 'none',
              borderRadius: '6px',
              cursor: isApplied ? 'default' : 'pointer',
              fontSize: '12px',
              fontWeight: '600'
            }}
          >
            {isApplied ? '✓ Applied' : 'Apply Now'}
          </button>
        )}
      </div>
    </div>
  );
}
